/// Fixed text metrics for layout tests: every line is 20 px high, natural
/// width is 100 px (brief T2 section 1.5).
static void FixTextMetrics() {
    vgww::ui::SetTextMeasure([](const std::wstring&, vgww::ui::FontToken, float) {
        return vgww::ui::Size{100.0f, 20.0f};
    });
}

static void TestThemeTokens() {
    using namespace vgww::ui;
    const FontSpec small = FontFor(FontToken::Small);
    CHECK(small.size == 11.0f && small.weight == 400);
    const FontSpec body = FontFor(FontToken::Body);
    CHECK(body.size == 13.0f && body.weight == 400);
    const FontSpec strong = FontFor(FontToken::BodyStrong);
    CHECK(strong.size == 13.0f && strong.weight == 600);
    const FontSpec number = FontFor(FontToken::Number);
    CHECK(number.size == 14.0f && number.weight == 400);
    const FontSpec stat = FontFor(FontToken::Stat);
    CHECK(stat.size == 24.0f && stat.weight == 600);
    const FontSpec section = FontFor(FontToken::Section);
    CHECK(section.size == 16.0f && section.weight == 600);
    const FontSpec title = FontFor(FontToken::Title);
    CHECK(title.size == 20.0f && title.weight == 600);

    const Theme& t = DarkTheme();
    CHECK(ColorFor(ColorToken::Bg).r == t.bg.r &&
          ColorFor(ColorToken::Bg).g == t.bg.g &&
          ColorFor(ColorToken::Bg).b == t.bg.b);
    CHECK(ColorFor(ColorToken::Panel).r == t.panel.r);
    CHECK(ColorFor(ColorToken::Accent).b == t.accent.b);
    CHECK(ColorFor(ColorToken::Danger).r == t.danger.r);
    CHECK(ColorFor(ColorToken::Success).g == t.success.g);
    CHECK(ColorFor(ColorToken::Warning).b == t.warning.b);

    // Fallback metrics (no injection): line height = size * 1.35, ASCII
    // advance 0.55 * size, non-ASCII 1.0 * size, clamped to max_width.
    SetTextMeasure(nullptr);
    const Size ascii = MeasureText(L"ab", FontToken::Body, 1000.0f);
    CHECK(std::fabs(ascii.h - 13.0f * 1.35f) < 0.001f);
    CHECK(std::fabs(ascii.w - 2.0f * 0.55f * 13.0f) < 0.001f);
    const Size cjk = MeasureText(L"中", FontToken::Body, 1000.0f);
    CHECK(std::fabs(cjk.w - 13.0f) < 0.001f);
    const Size clamped = MeasureText(std::wstring(100, L'a'), FontToken::Body, 50.0f);
    CHECK(clamped.w == 50.0f);
}

static void TestLayout() {
    using namespace vgww::ui;
    FixTextMetrics();
    auto panel = std::make_unique<StackPanel>(Orientation::Vertical, 8.0f, Padding{8,8,8,8});
    Text* a = static_cast<Text*>(panel->Add(std::make_unique<Text>(L"a")));  a->id = "a";
    Text* b = static_cast<Text*>(panel->Add(std::make_unique<Text>(L"bb"))); b->id = "b";
    Text* c = static_cast<Text*>(panel->Add(std::make_unique<Text>(L"ccc")));c->id = "c";
    // Text height = line-height token (the test injects fixed glyph metrics:
    // 20 per line under FakeTextMetrics)
    panel->Arrange({0,0,200,500});
    CHECK(panel->desired().h == 8 + 20 + 8 + 20 + 8 + 20 + 8);   // 92
    CHECK(a->bounds().y == 8); CHECK(b->bounds().y == 36); CHECK(c->bounds().y == 64);
    CHECK(c->bounds().w == 200 - 16);                            // Stretch by default
    CHECK(panel->HitTest({10,40})->id == "b");
    CHECK(panel->HitTest({10,90}) == nullptr);                   // no child below the padding
    // Supplements: tree links, measure-cache invalidation, hidden/disabled.
    CHECK(a->parent() == panel.get());
    CHECK(panel->children().size() == 3);
    SetTextMeasure([](const std::wstring& text, FontToken, float) {
        return Size{100.0f, text.size() > 3 ? 40.0f : 20.0f};
    });
    a->SetText(L"aaaa");                    // 20 -> 40 after re-measure
    CHECK(a->content_rev == 1);
    panel->Arrange({0,0,200,500});
    CHECK(a->desired().h == 40.0f);
    CHECK(panel->desired().h == 8 + 40 + 8 + 20 + 8 + 20 + 8);   // 112
    a->SetText(L"a");
    panel->Arrange({0,0,200,500});
    CHECK(panel->desired().h == 92.0f);
    CHECK(a->content_rev == 2);
    FixTextMetrics();

    b->visible = false;
    panel->InvalidateLayout();
    panel->Arrange({0,0,200,500});
    CHECK(panel->desired().h == 8 + 20 + 8 + 20 + 8);            // 64
    CHECK(panel->HitTest({10,40})->id == "c");                   // b hidden, c moved up
    b->visible = true;
    panel->InvalidateLayout();
    panel->Arrange({0,0,200,500});
    CHECK(panel->desired().h == 92.0f);

    b->enabled = false;                                          // disabled is not hit-testable
    CHECK(panel->HitTest({10,40}) == nullptr);
    b->enabled = true;
    CHECK(panel->HitTest({10,40})->id == "b");
}

