/// Test-local element with a fixed desired size (ScrollView content).
class FixedBox : public vgww::ui::Element {
public:
    FixedBox(float w, float h) : w_(w), h_(h) {}

protected:
    vgww::ui::Size MeasureCore(vgww::ui::Size) override {
        return vgww::ui::Size{w_, h_};
    }

private:
    float w_;
    float h_;
};

/// Test-local element that fills the available size and counts measures
/// (pins the Measure cache keyed by available size).
class CountingFillBox : public vgww::ui::Element {
public:
    int measures = 0;

protected:
    vgww::ui::Size MeasureCore(vgww::ui::Size available) override {
        ++measures;
        return available;
    }
};

/// Test-local element that paints its own bounds on RenderCore: the recorded
/// DrawOp rect equals the element bounds, so cull verdicts are exactly
/// assertable (which child drew, and where).
class CullPaintBox : public vgww::ui::Element {
public:
    CullPaintBox(float w, float h) : w_(w), h_(h) {}

protected:
    vgww::ui::Size MeasureCore(vgww::ui::Size) override {
        return vgww::ui::Size{w_, h_};
    }
    void RenderCore(vgww::ui::RenderCtx& ctx) override {
        ctx.FillRect(bounds_, vgww::ui::Color{1.0f, 1.0f, 1.0f, 1.0f});
    }

private:
    float w_;
    float h_;
};

