/// Types `text` into a text input (clears first): programmatic SetValue does
/// not fire on_changed, real keystrokes do.
static void TypeInto(vgww::ui::TextInputElement& input, const std::wstring& text) {
    input.SetValue(std::wstring());
    for (const wchar_t ch : text) {
        input.OnChar(ch);
    }
}

static bool DialogTextsContaining(vgww::ui::DialogHost& dialog,
                                  const std::wstring& part) {
    std::vector<std::wstring> texts;
    CollectTexts(dialog, texts);
    for (const std::wstring& candidate : texts) {
        if (candidate.find(part) != std::wstring::npos) {
            return true;
        }
    }
    return false;
}

// batch22 fix1: navigating to Settings BEFORE the first real snapshot must not
// poison the form. The first (empty) snapshot fills the fields; when the real
// one arrives the page must self-heal instead of treating the empty fill as
// "unsaved user edits" and never refreshing again.
//   T1 empty -> real : fields become the real values (RED before the fix)
//   T2 user edit + a newer snapshot : the edit survives (protection kept)
//   T3 after healing the ordinary Save reaches the command queue
static void TestSettingsEarlyEmptySnapshotHeals() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);

    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string start_error;
    CHECK(controller.Start(start_error));

    // A snapshot that has never been populated (the publisher's seed).
    UiSnapshot empty;
    empty.seq = 0;

    UiApp app;
    app.Compose(controller, empty);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});
    // Early navigation, exactly like the bug report.
    app.router().Navigate("settings");
    app.Update(empty);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});

    const auto text_value = [&](const char* id) -> std::wstring {
        auto* input = dynamic_cast<TextInputElement*>(FindById(app.root(), id));
        return input != nullptr ? input->value() : std::wstring(L"<missing>");
    };
    // The poisoned state the report describes (empty snapshot values).
    CHECK(text_value("settings.web_port") == L"0");
    CHECK(text_value("settings.gateway_ip").empty());

    // The real snapshot arrives: /api/config true values from the report.
    UiSnapshot real = MakeRulesSnapshot(1, 1);
    ConfigView& view = real.config;
    view.adapter = "Ethernet 2";
    view.mode = "main";
    view.gateway_ip = "192.168.0.240";
    view.gateway_mask = "255.255.255.0";
    view.gateway_mac = "02:00:00:00:00:01";
    view.dhcp_enabled = true;
    view.dhcp_pool_start = "192.168.0.100";
    view.dhcp_pool_end = "192.168.0.200";
    view.dhcp_lease_s = 86400;
    view.dhcp_dns = {"1.1.1.1"};
    view.ipv6_enabled = true;
    view.ula_prefix = "fd00:0000:0000:0000:0000:0000:0000:0000";
    view.prefix_len = 64;
    view.ra_lifetime_s = 1800;
    view.ipv6_dns = {"fd00::1"};
    view.dhcp6_enabled = true;
    view.dhcp6_pool_start = "fd00:0000:0000:0000:0000:0000:0000:1000";
    view.dhcp6_pool_end = "fd00:0000:0000:0000:0000:0000:0000:1fff";
    view.dhcp6_lease_s = 3600;
    view.web_port = 18080;
    view.web_bind = "127.0.0.1";
    view.vlan_id = 0;
    view.bridge_enabled = false;
    view.bridge_up = "NIC 1";
    view.bridge_down = "NIC 2";
    view.bridge_table_size = 4096;
    app.Update(real);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});

    // T1: every field self-heals to the real values (this is RED before the fix:
    // the draft was filled from the empty snapshot and marked "user edited").
    CHECK(text_value("settings.web_port") == L"18080");
    CHECK(text_value("settings.gateway_ip") == L"192.168.0.240");
    CHECK(text_value("settings.dhcp6_lease_seconds") == L"3600");
    CHECK(text_value("settings.bridge_table_size") == L"4096");
    // Replaying the same snapshot keeps it stable (no oscillation).
    app.Update(real);
    CHECK(text_value("settings.web_port") == L"18080");
    CHECK(text_value("settings.gateway_ip") == L"192.168.0.240");

    // T2: a real user edit must still be protected from a newer snapshot.
    // Stay inside the DHCP pool's subnet so the save below is genuinely valid
    // (an inconsistent gateway/pool pair is a legitimate validation refusal and
    // would test something else).
    if (auto* gw = dynamic_cast<TextInputElement*>(
            FindById(app.root(), "settings.gateway_ip"))) {
        TypeInto(*gw, L"192.168.0.254");
    }
    UiSnapshot real2 = real;
    real2.seq = 2;
    real2.config.gateway_ip = "172.16.0.1";
    real2.config.web_port = 19000;
    app.Update(real2);
    CHECK(text_value("settings.gateway_ip") == L"192.168.0.254");  // edit kept

    // T3: the ordinary Save path now reaches the command queue (before the fix
    // the draft held 0/empty values and ValidateConfig rejected the save).
    auto* save = dynamic_cast<Button*>(FindById(app.root(), "settings.save"));
    auto* dialog = dynamic_cast<DialogHost*>(FindById(app.root(), "settings.dialog"));
    CHECK(save != nullptr);
    if (save != nullptr) {
        executor.commands.clear();
        ClickElement(*save);
        CHECK(WaitForCommands(executor, 1, controller));
        CHECK(executor.commands.size() == 1);
        if (executor.commands.size() == 1) {
            const auto* cmd = std::get_if<SaveConfigCmd>(&executor.commands[0]);
            CHECK(cmd != nullptr);
            if (cmd != nullptr) {
                // The form froze on the first real snapshot (the user's edit
                // came later), so the healed values are what gets saved.
                CHECK(cmd->config.web.port == 18080u);
                CHECK(cmd->config.bridge.mac_table_size == 4096u);
                CHECK(cmd->config.ipv6.dhcpv6.lease_seconds == 3600u);
                CHECK(vgww::core::FormatIpv4(cmd->config.gateway.ipv4) ==
                      "192.168.0.254");  // the user's edit is what gets saved
            }
        }
    }
    if (dialog != nullptr) {
        CHECK(!dialog->open());  // no "invalid number" error dialog
    }
    I18n::Instance().SetLang(Lang::ZhCN);
}

// batch39 (user: an operator double-clicking Save must not post two identical
// SaveConfigCmds; the apply restarts the data plane, so a re-entry inside the
// apply window is dropped, and the guard self-clears afterwards).
static void TestB39SettingsSaveDoubleClickGuard() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);

    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string start_error;
    CHECK(controller.Start(start_error));

    UiApp app;
    UiSnapshot empty;
    empty.seq = 0;
    app.Compose(controller, empty);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});
    app.router().Navigate("settings");
    app.Update(empty);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});

    UiSnapshot real = MakeRulesSnapshot(1, 1);
    ConfigView& view = real.config;
    view.adapter = "Ethernet 2";
    view.mode = "main";
    view.gateway_ip = "192.168.0.240";
    view.gateway_mask = "255.255.255.0";
    view.gateway_mac = "02:00:00:00:00:01";
    view.dhcp_enabled = true;
    view.dhcp_pool_start = "192.168.0.100";
    view.dhcp_pool_end = "192.168.0.200";
    view.dhcp_lease_s = 86400;
    view.dhcp_dns = {"1.1.1.1"};
    view.ipv6_enabled = true;
    view.ula_prefix = "fd00:0000:0000:0000:0000:0000:0000:0000";
    view.prefix_len = 64;
    view.ra_lifetime_s = 1800;
    view.ipv6_dns = {"fd00::1"};
    view.dhcp6_enabled = true;
    view.dhcp6_pool_start = "fd00:0000:0000:0000:0000:0000:0000:1000";
    view.dhcp6_pool_end = "fd00:0000:0000:0000:0000:0000:0000:1fff";
    view.dhcp6_lease_s = 3600;
    view.web_port = 18080;
    view.web_bind = "127.0.0.1";
    view.vlan_id = 0;
    view.bridge_enabled = false;
    view.bridge_up = "NIC 1";
    view.bridge_down = "NIC 2";
    view.bridge_table_size = 4096;
    app.Update(real);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});

    auto* save = dynamic_cast<Button*>(FindById(app.root(), "settings.save"));
    CHECK(save != nullptr);
    if (save == nullptr) {
        return;
    }

    // First click posts exactly one command.
    executor.commands.clear();
    ClickElement(*save);
    CHECK(WaitForCommands(executor, 1, controller));
    CHECK(executor.commands.size() == 1);

    // RED before the guard: an immediate second click used to post a second
    // identical SaveConfigCmd. Now it is dropped while the state is unchanged.
    ClickElement(*save);
    CHECK(!WaitForCommands(executor, 2, controller));
    CHECK(executor.commands.size() == 1);

    // A real edit disarms the guard; the next save works again (one more
    // command). (GREEN after the fix; the earlier timer-based window wrongly
    // swallowed this legitimate save-then-edit-then-save sequence.)
    if (auto* gw = dynamic_cast<TextInputElement*>(
            FindById(app.root(), "settings.gateway_ip"))) {
        TypeInto(*gw, L"192.168.0.253");
    }
    ClickElement(*save);
    CHECK(WaitForCommands(executor, 2, controller));
    CHECK(executor.commands.size() == 2);
    I18n::Instance().SetLang(Lang::ZhCN);
}

// batch22 A8-1: the Web token field is write-only editable. Red anchors:
// (a) an EMPTY field + save keeps the on-disk token (no accidental wipe);
// (b) a typed value replaces it; (c) only the confirmed Clear empties it.
static void TestA8TokenEdit() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::En);

    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string start_error;
    CHECK(controller.Start(start_error));

    // An on-disk config that already carries a token.
    const std::filesystem::path temp_config =
        std::filesystem::temp_directory_path() / "vgww_a8_token_test.json";
    {
        const char* json =
            "{\n"
            "  \"mode\": \"main\",\n"
            "  \"adapter\": \"Ethernet 2\",\n"
            "  \"gateway\": {\"ipv4\": \"192.168.1.1\", \"mask\": \"255.255.255.0\","
            " \"mac\": \"02:00:00:00:00:01\"},\n"
            "  \"dhcp\": {\"enabled\": true, \"pool_start\": \"192.168.1.100\","
            " \"pool_end\": \"192.168.1.200\", \"lease_hours\": 24},\n"
            "  \"ipv6\": {\"enabled\": false, \"ula_prefix\": \"fd00::/64\","
            " \"ra_lifetime_s\": 1800, \"dns\": []},\n"
            "  \"perf\": {\"workers\": 4, \"max_conns\": 2048},\n"
            "  \"web\": {\"port\": 8080, \"token\": \"keep-me\"},\n"
            "  \"bridge\": {\"enabled\": false, \"upstream\": \"NIC 1\","
            " \"downstream\": \"NIC 2\", \"mac_table_size\": 4096}\n"
            "}\n";
        std::FILE* file = nullptr;
        CHECK(::fopen_s(&file, temp_config.string().c_str(), "wb") == 0);
        if (file != nullptr) {
            CHECK(std::fwrite(json, 1, std::strlen(json), file) ==
                  std::strlen(json));
            std::fclose(file);
        }
    }

    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    ConfigView& view = snapshot.config;
    view.adapter = "Ethernet 2";
    view.mode = "main";
    view.gateway_ip = "192.168.1.1";
    view.gateway_mask = "255.255.255.0";
    view.gateway_mac = "02:00:00:00:00:01";
    view.dhcp_enabled = true;
    view.dhcp_pool_start = "192.168.1.100";
    view.dhcp_pool_end = "192.168.1.200";
    view.dhcp_lease_s = 86400;
    view.dhcp_dns = {"1.1.1.1", "8.8.8.8"};
    view.ipv6_enabled = true;
    view.ula_prefix = "fd00:0000:0000:0000:0000:0000:0000:0000";
    view.prefix_len = 64;
    view.ra_lifetime_s = 1800;
    view.ipv6_dns = {"fd00::1"};
    view.dhcp6_enabled = true;
    view.dhcp6_pool_start = "fd00:0000:0000:0000:0000:0000:0000:1000";
    view.dhcp6_pool_end = "fd00:0000:0000:0000:0000:0000:0000:1fff";
    view.dhcp6_lease_s = 3600;
    view.web_port = 8080;
    view.vlan_id = 0;
    view.bridge_enabled = false;
    view.bridge_up = "NIC 1";
    view.bridge_down = "NIC 2";
    view.bridge_table_size = 4096;
    view.perf_workers = 4;
    view.perf_max_conns = 2048;
    view.config_path = temp_config.string();

    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});
    app.router().Navigate("settings");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});

    // batch25a: the token field now lives in the collapsed advanced tier.
    if (auto* adv = dynamic_cast<Button*>(
            FindById(app.root(), "settings.advanced.toggle"))) {
        ClickElement(*adv);
        app.root().Arrange({0.0f, 0.0f, 1280.0f, 1000.0f});
    }

    auto* token = dynamic_cast<TextInputElement*>(FindById(app.root(), "settings.token"));
    auto* clear = dynamic_cast<Button*>(FindById(app.root(), "settings.token_clear"));
    auto* save = dynamic_cast<Button*>(FindById(app.root(), "settings.save"));
    auto* dialog = dynamic_cast<DialogHost*>(FindById(app.root(), "settings.dialog"));
    CHECK(token != nullptr && clear != nullptr && save != nullptr && dialog != nullptr);
    if (token == nullptr || clear == nullptr || save == nullptr || dialog == nullptr) {
        return;
    }
    // Write-only: the current secret is never displayed.
    CHECK(token->value().empty());

    const auto save_and_get_token = [&]() -> std::wstring {
        executor.commands.clear();
        ClickElement(*save);
        if (!WaitForCommands(executor, 1, controller)) {
            return L"<no-command>";
        }
        const auto* cmd = std::get_if<SaveConfigCmd>(&executor.commands[0]);
        if (cmd == nullptr) {
            return L"<wrong-command>";
        }
        return std::wstring(cmd->config.web.token.begin(),
                            cmd->config.web.token.end());
    };

    // (a) empty field -> the on-disk token survives an unrelated save.
    CHECK(save_and_get_token() == L"keep-me");

    // (b) a typed value replaces it.
    TypeInto(*token, L"new-secret");
    CHECK(save_and_get_token() == L"new-secret");

    // (c) Clear is explicit + confirmed: the dialog gates the action.
    ClickElement(*clear);
    CHECK(dialog->open());
    if (dialog->open()) {
        CHECK(dialog->OnKeyDown(0x0D));  // accept the confirmation
    }
    CHECK(save_and_get_token() == L"");
    std::filesystem::remove(temp_config);
    I18n::Instance().SetLang(Lang::ZhCN);
}

// batch22 A7: the dashboard identity/protocol row. Red anchors: every tile
// value maps from the real core field, and a missing source renders the "not
// set" placeholder instead of a fabricated value.
static void TestA7DashboardCards() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::En);

    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string start_error;
    CHECK(controller.Start(start_error));

    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    snapshot.config.gateway_ip = "192.168.1.1";
    snapshot.config.ipv6_enabled = true;
    snapshot.counters.tcp_accepted = 1234;
    snapshot.counters.rx_dropped = 7;
    snapshot.counters.host_passthrough = 42;
    snapshot.counters.rx_vlan_frames = 11;
    snapshot.counters.tx_vlan_frames = 22;
    snapshot.system.proc_virt_bytes = 3 * 1024 * 1024;  // 3 MiB

    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1200.0f});
    app.router().Navigate("dashboard");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 1200.0f});

    const auto text_of = [&](const char* id) -> std::wstring {
        auto* text = dynamic_cast<Text*>(FindById(app.root(), id));
        return text != nullptr ? text->text() : std::wstring(L"<missing>");
    };
    CHECK(text_of("dash.gw") == L"192.168.1.1");
    CHECK(text_of("dash.ipv6") == I18n::Instance().T(Str::CommonYes));
    CHECK(text_of("dash.tcp") == FormatCount(1234));  // thousands separators
    CHECK(text_of("dash.drops") == L"7");
    CHECK(text_of("dash.pass") == L"42");
    CHECK(text_of("dash.vlan.rx") == L"11");
    CHECK(text_of("dash.vlan.tx") == L"22");
    CHECK(!text_of("dash.vmem").empty());
    CHECK(text_of("dash.vmem") != L"<missing>");

    // Honest omission: no gateway address in the model -> placeholder, never a
    // fabricated address.
    snapshot.config.gateway_ip.clear();
    snapshot.config.ipv6_enabled = false;
    app.Update(snapshot);
    CHECK(text_of("dash.gw") == I18n::Instance().T(Str::CommonNotSet));
    CHECK(text_of("dash.ipv6") == I18n::Instance().T(Str::CommonNo));
    I18n::Instance().SetLang(Lang::ZhCN);
}

