// ============================================================================
// T12-F2: aesthetic round 1 part B - settings overlap, compact add buttons,
// bridge badge/label alignment, leases empty-state spacing.
// ============================================================================

static void CollectLeafBounds(vgww::ui::Element& root,
                              std::vector<vgww::ui::Rect>& out) {
    for (const auto& child : root.children()) {
        if (!child->visible) {
            continue;
        }
        // batch27: a ScrollView clips its content to its viewport, so children
        // scrolled past the bottom edge are NOT painted where their raw bounds
        // say. Clip to the viewport before recording a leaf, otherwise the
        // (unpainted) overflow reads as an overlap with the page footer.
        if (auto* view = dynamic_cast<vgww::ui::ScrollView*>(child.get())) {
            std::vector<vgww::ui::Rect> inner;
            CollectLeafBounds(*child, inner);
            const vgww::ui::Rect vp = view->bounds();
            for (const vgww::ui::Rect& r : inner) {
                const float x0 = std::max(r.x, vp.x);
                const float y0 = std::max(r.y, vp.y);
                const float x1 = std::min(r.x + r.w, vp.x + vp.w);
                const float y1 = std::min(r.y + r.h, vp.y + vp.h);
                if (x1 > x0 && y1 > y0) {
                    out.push_back(vgww::ui::Rect{x0, y0, x1 - x0, y1 - y0});
                }
            }
            continue;
        }
        if (child->children().empty()) {
            if (dynamic_cast<vgww::ui::Text*>(child.get()) != nullptr ||
                dynamic_cast<vgww::ui::TextInputElement*>(child.get()) !=
                    nullptr ||
                dynamic_cast<vgww::ui::Checkbox*>(child.get()) != nullptr ||
                dynamic_cast<vgww::ui::SelectElement*>(child.get()) != nullptr ||
                dynamic_cast<vgww::ui::Button*>(child.get()) != nullptr) {
                out.push_back(child->bounds());
            }
        } else {
            CollectLeafBounds(*child, out);
        }
    }
}

static void TestSettingsNoOverlap() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);

    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    ConfigView& view = snapshot.config;
    view.mode = "main";
    view.gateway_ip = "192.168.1.1";
    view.gateway_mask = "255.255.255.0";
    view.gateway_mac = "02:00:00:00:00:01";
    view.dhcp_enabled = true;
    view.dhcp_pool_start = "192.168.1.100";
    view.dhcp_pool_end = "192.168.1.200";
    view.dhcp_lease_s = 86400;
    view.dhcp_dns = {"1.1.1.1", "8.8.8.8"};
    view.ipv6_enabled = true;
    view.ula_prefix = "fd00:0000:0000:0000:0000:0000:0000:0000";
    view.prefix_len = 64;
    view.ra_lifetime_s = 1800;
    view.ipv6_dns = {"fd00::1"};
    view.dhcp6_enabled = true;
    view.dhcp6_pool_start = "fd00:0000:0000:0000:0000:0000:0000:1000";
    view.dhcp6_pool_end = "fd00:0000:0000:0000:0000:0000:0000:1fff";
    view.dhcp6_lease_s = 3600;
    view.web_port = 8080;
    view.bridge_up = "NIC 1";
    view.bridge_down = "NIC 2";
    view.bridge_table_size = 4096;
    view.config_path = "";

    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    app.router().Navigate("settings");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});

    // batch25a: expand the advanced tier so every professional field is in
    // the layout (the tier is collapsed by default).
    if (auto* adv = dynamic_cast<Button*>(
            FindById(app.root(), "settings.advanced.toggle"))) {
        ClickElement(*adv);
        app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    }

    // B1: no visible leaf element may overlap another (labels, fields, group
    // headings all line up on the 8 pt grid).
    std::vector<Rect> leaves;
    CollectLeafBounds(app.root(), leaves);
    CHECK(leaves.size() >= 30u);
    std::size_t overlaps = 0;
    for (std::size_t a = 0; a < leaves.size(); ++a) {
        for (std::size_t b = a + 1; b < leaves.size(); ++b) {
            const Rect& r1 = leaves[a];
            const Rect& r2 = leaves[b];
            if (r1.w > 0.0f && r2.w > 0.0f && r1.h > 0.0f && r2.h > 0.0f &&
                r1.x < r2.x + r2.w && r2.x < r1.x + r1.w &&
                r1.y < r2.y + r2.h && r2.y < r1.y + r1.h) {
                ++overlaps;
            }
        }
    }
    CHECK(overlaps == 0);
    I18n::Instance().SetLang(Lang::ZhCN);
}

