static void TestLeasesEmptySpacing() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);  // no leases
    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    app.router().Navigate("leases");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    auto* table = dynamic_cast<TableElement*>(FindById(app.root(), "leases.table.v4"));
    auto* empty = FindById(app.root(), "leases.table.v4.empty");
    CHECK(table != nullptr && empty != nullptr);
    // batch27 D2: the placeholder is now centred INSIDE the table region (below
    // its header band), so it is no longer required to sit below the whole
    // table box - it must be inside the viewport, below the header, and its
    // top/bottom whitespace must match.
    if (table != nullptr && empty != nullptr) {
        const float header_bottom =
            table->bounds().y + TableElement::header_height();
        const float region_bottom = table->bounds().y + table->bounds().h;
        CHECK(empty->bounds().y >= header_bottom);
        CHECK(empty->bounds().y + empty->bounds().h <= region_bottom + 0.5f);
        const float above = empty->bounds().y - header_bottom;
        const float below = region_bottom - (empty->bounds().y +
                                             empty->bounds().h);
        CHECK(std::fabs(above - below) <= 8.0f);
    }
    I18n::Instance().SetLang(Lang::ZhCN);
}

