    page->Arrange({0.0f, 0.0f, 800.0f, 600.0f});
    std::vector<Button*> buttons;
    CollectButtons(*dialog, buttons);
    CHECK(buttons.size() == 2);
    if (buttons.size() != 2) {
        return;
    }
