static void TestBusyToastOnFullQueue() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    GatedExecutor executor;
    UiController controller(source, executor);
    std::string error;
    CHECK(controller.Start(error));
    UiSnapshot snap;
    snap.seq = 1;
    snap.dataplane_running = true;
    UiApp app;
    app.Compose(controller, snap);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    app.router().Navigate("portmap");
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});

    // The worker takes one command and blocks; the queue then holds 64.
    CHECK(controller.Post(Command{AddBanCmd{"mac", "gate"}}));
    const auto deadline = std::chrono::steady_clock::now() +
                          std::chrono::seconds(3);
    while (!executor.entered.load(std::memory_order_acquire) &&
           std::chrono::steady_clock::now() < deadline) {
        std::this_thread::sleep_for(std::chrono::milliseconds(2));
    }
    CHECK(executor.entered.load(std::memory_order_acquire));
    for (int i = 0; i < 64; ++i) {
        CHECK(controller.Post(
            Command{AddBanCmd{"mac", "q" + std::to_string(i)}}));
    }
    CHECK(!controller.Post(
        Command{AddBanCmd{"mac", "fill-check"}}));  // 65th rejected

    // Submitting a port-map form hits the full queue: the UI must surface a
    // busy toast instead of silently dropping the command (U6).
    auto* add = dynamic_cast<Button*>(FindById(app.root(), "portmap.add"));
    CHECK(add != nullptr);
    ClickElement(*add);
    auto* dialog =
        dynamic_cast<DialogHost*>(FindById(app.root(), "portmap.dialog"));
    CHECK(dialog != nullptr && dialog->open() &&
          dialog->mode() == DialogHost::Mode::Form);
    auto set_field = [&](const char* id, const std::wstring& value) {
        Element* editor = dialog->form_field(id);
        CHECK(editor != nullptr);
        if (auto* input = dynamic_cast<TextInputElement*>(editor)) {
            input->SetValue(value);
        }
    };
    set_field("wan_port", L"8080");
    set_field("lan_ip", L"192.168.1.50");
    set_field("lan_port", L"80");
    const std::size_t before_toasts = app.toasts().active_count();
    CHECK(dialog->OnKeyDown(0x0D));  // VK_RETURN -> SubmitForm
    CHECK(app.toasts().active_count() > before_toasts);  // U6 red: no toast
    executor.release.store(true, std::memory_order_release);
    controller.Stop();
    I18n::Instance().SetLang(Lang::ZhCN);
}

