// T8: metrics op reads window-level counters (all headless-safe). fps and
// dropped_frames are genuinely unavailable and must be null, not a faked 0.
static void TestDebugMetrics() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* box = static_cast<FixedBox*>(root.Add(std::make_unique<FixedBox>(40.0f, 40.0f)));
    box->id = "box";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    const auto m = c.Metrics();
    CHECK(m.value("ok", false) == true);
    CHECK(m.contains("paint_count") && m.at("paint_count") == 0);   // headless
    CHECK(m.contains("tick_count") && m.at("tick_count") == 0);
    CHECK(m.contains("frame_time_us") && m.at("frame_time_us").is_number());
    CHECK(m.contains("tick_time_us") && m.at("tick_time_us").is_number());
    CHECK(m.contains("layout_requests") && m.at("layout_requests").is_number());
    CHECK(m.contains("animation_frames") && m.at("animation_frames").is_number());
    CHECK(m.contains("dirty_rect") && m.at("dirty_rect").is_array() &&
          m.at("dirty_rect").size() == 4);
    CHECK(m.contains("scale") && m.at("scale").is_number());
    CHECK(m.contains("dpi") && m.at("dpi").is_number());
    // M5: fps/dropped_frames are now real frame statistics (numbers), not
    // fabricated zeroes and never reserved nulls.
    CHECK(m.contains("fps") && m.at("fps").is_number());
    CHECK(m.contains("dropped_frames") && m.at("dropped_frames").is_number());

    // A backfilled tick is observable through the counter.
    w.RecordTickForTest(1234);
    const auto m2 = c.Metrics();
    CHECK(m2.at("tick_count") == 1);
    CHECK(m2.at("tick_time_us") == 1234);
}

// ---------------------------------------------------------------------------
// M5 (2026-10-12): metrics gate - real fps / dropped-frame statistics via
// RecordFrameForTest, renderer draw-op counterts and cache counters surface
// through Metrics(). Headless stays a zero baseline (never fabricated).
// ---------------------------------------------------------------------------

// T1 FrameStatsBasic: 60 x (8000us paint, 16000us interval) -> ~60 fps, zero
// dropped frames, and each seam record counts as one completed paint.
static void TestFrameStatsBasic() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    for (int i = 0; i < 60; ++i) {
        w.RecordFrameForTest(8000, 16000);
    }
    const double fps = w.fps();
    CHECK(std::fabs(fps - 62.5) < 7.5);   // 60 * 1e6 / (60 * 16000) = 62.5
    CHECK(w.dropped_frames() == 0);
    CHECK(w.paint_count() == 60);
    CHECK(w.frame_time_max_us() == 8000);

    const auto m = c.Metrics();
    CHECK(m.at("fps").get<double>() > 55.0);
    CHECK(m.at("dropped_frames") == 0);
    CHECK(m.at("fps_samples") == 60);
    CHECK(m.at("frame_time_max_us") == 8000);
}

// T2 Dropped (monotonic): an over-budget paint (20000us) counts a dropped
// frame and Metrics() reads never decrease the counter.
static void TestDroppedMonotonic() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    for (int i = 0; i < 3; ++i) {
        w.RecordFrameForTest(8000, 16000);
    }
    const auto m0 = c.Metrics();
    const uint64_t d0 = m0.at("dropped_frames").get<uint64_t>();
    w.RecordFrameForTest(20000, 16000);
    const auto m1 = c.Metrics();
    CHECK(m1.at("dropped_frames").get<uint64_t>() == d0 + 1);
    const auto m2 = c.Metrics();
    CHECK(m2.at("dropped_frames").get<uint64_t>() >=
          m1.at("dropped_frames").get<uint64_t>());
    CHECK(w.dropped_frames() == d0 + 1);
}

// T3 ThresholdBoundary: paint_us exactly == the 16700us budget is NOT a drop;
// one us over is exactly one drop.
static void TestThresholdBoundary() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    w.RecordFrameForTest(16700, 16000);
    CHECK(w.dropped_frames() == 0);
    w.RecordFrameForTest(16700, 16000);
    CHECK(w.dropped_frames() == 0);
    w.RecordFrameForTest(16701, 16000);
    CHECK(w.dropped_frames() == 1);
}

