// T9 CacheCounters: Metrics mirrors the renderer's live layout/measure cache
// counters (lookups >= hits; hits > 0 after a repeated draw).
static void TestCacheCounters() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    RenderCtx& ctx = w.renderer();
    std::string error;
    const bool ok = ctx.Initialize(error);
    CHECK(ok);
    if (ok) {
        const Rect r{0.0f, 0.0f, 40.0f, 20.0f};
        const Color c = ColorFor(ColorToken::Text);
        ctx.DrawText(L"cache", r, FontToken::Body, c, Align::Start);
        ctx.DrawText(L"cache", r, FontToken::Body, c, Align::Start);
        CHECK(ctx.LayoutCacheLookups() >= ctx.LayoutCacheHits());
        CHECK(ctx.LayoutCacheHits() > 0);
        UiDebugController ctl;
        ctl.Bind(&root, &w, nullptr, nullptr);
        const auto m = ctl.Metrics();
        CHECK(m.at("layout_cache_lookups").get<size_t>() ==
              ctx.LayoutCacheLookups());
        CHECK(m.at("layout_cache_hits").get<size_t>() == ctx.LayoutCacheHits());
        CHECK(m.at("measure_cache_size").get<size_t>() ==
              ctx.MeasureCacheSize());
    }
    ctx.Shutdown();
}

// T10 IdleGapClearWindow: a burst, then one interval beyond kIdleGapUs
// (83500us) clears the rolling window (fps 0, no samples); a fresh active
// burst rebuilds it so fps recovers.
static void TestIdleGapClearWindow() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    for (int i = 0; i < 60; ++i) {
        w.RecordFrameForTest(8000, 16000);
    }
    CHECK(w.fps() > 55.0);
    CHECK(w.fps_samples() == 60);
    // A true idle gap (90000us > 83500us): the window is cleared.
    w.RecordFrameForTest(8000, 90000);
    CHECK(w.fps() == 0.0);
    CHECK(w.fps_samples() == 0);
    // A fresh active burst rebuilds the window; fps recovers.
    for (int i = 0; i < 3; ++i) {
        w.RecordFrameForTest(8000, 16000);
    }
    CHECK(w.fps_samples() == 3);
    CHECK(w.fps() > 0.0);
}

// T8 defect 1 (audit B2): UiApp::OnTick must backfill the window tick counters
// (previously only tests called RecordTickForTest, so live tick_count stayed 0).
static void TestDebugTickCountBackfill() {
    using namespace vgww::ui;
    FixTextMetrics();
    ShellFakeSource source;
    ShellFakeExecutor executor;
    UiController controller(source, executor);
    UiApp app;
    UiSnapshot first;
    first.seq = 1;
    app.Compose(controller, first);
    VgwwWindow& w = app.window();
    UiDebugController c;
    c.Bind(&app.root(), &w, nullptr, nullptr);

    const auto before = c.Metrics();
    CHECK(before.at("tick_count") == 0);
    // The app tick (the same path the 200 ms timer drives) must backfill.
    app.OnTickForTest();
    const auto after = c.Metrics();
    CHECK(after.at("tick_count") == 1);
    CHECK(after.at("tick_time_us").is_number());
    app.OnTickForTest();
    const auto after2 = c.Metrics();
    CHECK(after2.at("tick_count") == 2);
}

// P94: the driver-repair outcome used to live only in a toast (transient) and
// stderr. A failed repair is exactly what a post-mortem needs, and the web
// route already records the request - the result must reach the audit ring.
static void TestP94RepairOutcomeIsAudited() {
    using namespace vgww::ui;
    FixTextMetrics();
    console_log::ClearForTest();
    ShellFakeSource source;
    ShellFakeExecutor executor;
    UiController controller(source, executor);
    UiApp app;
    UiSnapshot first;
    first.seq = 1;
    app.Compose(controller, first);

    // A failed repair must leave a matching audit line.
    app.SetRepairOutcomeForTest(false, L"access denied");
    app.OnTickForTest();
    bool saw_failed = false;
    for (const auto& line : console_log::Snapshot()) {
        if (line.find(L"[audit]") != std::wstring::npos &&
            line.find(L"driver repair failed") != std::wstring::npos) {
            saw_failed = true;
        }
    }
    CHECK(saw_failed);

    // A successful repair audits the success line (the guard is not a blanket
    // suffix).
    console_log::ClearForTest();
    app.SetRepairOutcomeForTest(true, L"");
    app.OnTickForTest();
    bool saw_ok = false;
    for (const auto& line : console_log::Snapshot()) {
        if (line.find(L"[audit]") != std::wstring::npos &&
            line.find(L"driver repair succeeded") != std::wstring::npos) {
            saw_ok = true;
        }
    }
    CHECK(saw_ok);
}

// P96: a failed native config save used to leave no audit line at all - only
// the toast. The web route already records its failures (P95); the native
// command must leave the same durable record.
static void TestP96UiConfigSaveFailureIsAudited() {
    using namespace vgww::ui;
    FixTextMetrics();
    console_log::ClearForTest();
    const std::string cfg_path = "test_ui_p96_config.json";
    std::remove(cfg_path.c_str());
    vgww::core::Config cfg;
    cfg.adapter = "Ethernet";
    bool ok = false;
    cfg.gateway.ipv4 = vgww::core::ParseIpv4("192.168.49.1", ok);
    cfg.gateway.mask = vgww::core::ParseIpv4("255.255.255.0", ok);
    vgww::core::ParseMac("30:fc:68:88:b4:99", cfg.gateway.mac);
    vgww::runtime::Dataplane dataplane(cfg);
    DataplaneCommandExecutor executor(dataplane, cfg_path);

    // An invalid document is rejected before any write.
    vgww::core::Config invalid;
    invalid.gateway.ipv4 = 0;
    const CommandResult rejected =
        executor.Execute(Command{SaveConfigCmd{std::move(invalid)}});
    CHECK(!rejected.ok);
    bool saw_rejected = false;
    for (const auto& line : console_log::Snapshot()) {
        if (line.find(L"[audit]") != std::wstring::npos &&
            line.find(L"config save rejected") != std::wstring::npos) {
            saw_rejected = true;
        }
    }
    CHECK(saw_rejected);

    // A directory at the config path makes the write fail after validation.
    console_log::ClearForTest();
    std::error_code ec;
    std::filesystem::remove(cfg_path, ec);
    CHECK(std::filesystem::create_directory(cfg_path, ec));
    const CommandResult failed =
        executor.Execute(Command{SaveConfigCmd{cfg}});
    CHECK(!failed.ok);
    bool saw_failed = false;
    for (const auto& line : console_log::Snapshot()) {
        if (line.find(L"[audit]") != std::wstring::npos &&
            line.find(L"config save failed") != std::wstring::npos) {
            saw_failed = true;
        }
    }
    CHECK(saw_failed);

    // A failing live-apply hook must audit the failure (the file is saved,
    // so this is the only durable record of the rejected switch).
    console_log::ClearForTest();
    std::filesystem::remove_all(cfg_path, ec);
    std::string write_err;
    CHECK(cfg.SaveToFile(cfg_path, write_err));
    int apply_calls = 0;
    DataplaneCommandExecutor applying(
        dataplane, cfg_path, {}, [&apply_calls](const vgww::core::Config&,
                                               std::wstring& error) {
            ++apply_calls;
            error = L"adapter busy";
            return false;
        });
    const CommandResult apply_failed =
        applying.Execute(Command{SaveConfigCmd{cfg}});
    CHECK(!apply_failed.ok);
    CHECK(1 == apply_calls);
    bool saw_apply_failed = false;
    for (const auto& line : console_log::Snapshot()) {
        if (line.find(L"[audit]") != std::wstring::npos &&
            line.find(L"config save failed (live apply)") !=
                std::wstring::npos) {
            saw_apply_failed = true;
        }
    }
    CHECK(saw_apply_failed);

    // An empty config path is refused before any write.
    console_log::ClearForTest();
    DataplaneCommandExecutor no_path(dataplane, "");
    const CommandResult no_path_result =
        no_path.Execute(Command{SaveConfigCmd{cfg}});
    CHECK(!no_path_result.ok);
    bool saw_no_path = false;
    for (const auto& line : console_log::Snapshot()) {
        if (line.find(L"[audit]") != std::wstring::npos &&
            line.find(L"config save rejected (no config path)") !=
                std::wstring::npos) {
            saw_no_path = true;
        }
    }
    CHECK(saw_no_path);

    std::filesystem::remove_all(cfg_path, ec);
}

// T8 defect 3 (audit B2): an injected modifier mask must not latch forever; a
// debug key op resets it so a later real Shift+Tab falls back to GetKeyState.
static void TestDebugModifierReset() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* a = static_cast<Button*>(root.Add(std::make_unique<Button>(L"A")));
    a->id = "a";
    auto* b = static_cast<Button*>(root.Add(std::make_unique<Button>(L"B")));
    b->id = "b";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);
    w.SetFocusForTest(a);

    // A debug key op with a shift modifier injects, then must reset.
    const auto k = c.RunOneCommand(
        {{"op", "key"}, {"name", "Tab"}, {"modifiers", {"shift"}}});
    CHECK(k.value("ok", false) == true);
    // The injected mask is not latched after the op returns.
    CHECK(w.modifiers_injected_for_test() == false);

    // Explicit reset seam drops the injection too.
    w.SetModifiersForTest(0x1u);
    CHECK(w.modifiers_injected_for_test() == true);
    w.ResetModifiersForTest();
    CHECK(w.modifiers_injected_for_test() == false);
    CHECK(w.modifiers_for_test() == 0u);
}

// T8: render op - record mode is render-target independent (headless OK);
// paint mode requires a live hwnd and reports blocked headless.
