// T8: tick op - deterministic time advance (no sleep). caret phase flips
// floor(ms/500); animation advances one dt frame; toast expiry via Tick.
static void TestDebugTick() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* input = static_cast<TextInputElement*>(
        root.Add(std::make_unique<TextInputElement>()));
    input->id = "tf";
    input->SetValue(L"ab");
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    // Focus the input so the caret blink has a target.
    w.SetFocusForTest(input);
    const bool before = input->caret_visible();
    const auto t = c.RunOneCommand({{"op", "tick"}, {"ms", 500}});
    CHECK(t.value("ok", false) == true);
    CHECK(t["data"].value("advanced_ms", 0) == 500);
    CHECK(t["data"].at("caret_flipped") == 1);
    CHECK(input->caret_visible() != before);  // one phase flip

    // 1100 ms -> floor(1100/500)=2 further flips -> net even -> back to the
    // phase it had before this second tick.
    const bool phase_before_t2 = input->caret_visible();
    const auto t2 = c.RunOneCommand({{"op", "tick"}, {"ms", 1100}});
    CHECK(t2["data"].at("caret_flipped") == 2);
    CHECK(input->caret_visible() == phase_before_t2);

    // Missing ms is a clean error.
    const auto bad = c.RunOneCommand({{"op", "tick"}});
    CHECK(bad.value("ok", false) == false);
}

// T8: drag op - aggregate pointer drag records the hit role/id per step and
// drives a Table column resize end to end.
static void TestDebugDrag() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* table = static_cast<TableElement*>(
        root.Add(std::make_unique<TableElement>()));
    table->id = "tbl";
    TableColumn c0; c0.width = 1.0f;
    TableColumn c1; c1.width = 1.0f;
    table->SetColumns({c0, c1});
    root.Arrange({0, 0, 400, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    // Grab the first column boundary (x == bounds.x + width0) in the header
    // band and drag it right; the aggregate op reports a multi-step path.
    const Rect tb = table->bounds();
    const float boundary_x = tb.x + table->resolved_widths().front();
    const auto d = c.RunOneCommand(
        {{"op", "drag"},
         {"from", {{"x", boundary_x}, {"y", tb.y + 4.0f}}},
         {"to", {{"x", boundary_x + 60.0f}, {"y", tb.y + 4.0f}}},
         {"steps", 4}});
    CHECK(d.value("ok", false) == true);
    CHECK(d["data"].value("consumed", false) == true);
    CHECK(d["data"].contains("path") && d["data"]["path"].is_array());
    CHECK(d["data"]["path"].size() == 4);
    CHECK(table->user_resized() == true);

    // Dragging an element id endpoint is also accepted.
    auto* box = static_cast<FixedBox*>(root.Add(std::make_unique<FixedBox>(30.0f, 30.0f)));
    box->id = "bx";
    root.Arrange({0, 0, 400, 400});
    const auto d2 = c.RunOneCommand(
        {{"op", "drag"}, {"from", "bx"}, {"to", "tbl"}, {"steps", 2}});
    CHECK(d2.value("ok", false) == true);
}

