// T8: type op UTF-8 fix - decode UTF-8 to wchar; `typed` counts accepted wchar
// (ASCII accepted, non-ASCII rejected by TextInput's ASCII guard) and never
// reports the byte length (the old lie).
static void TestDebugTypeUtf8() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* input = static_cast<TextInputElement*>(
        root.Add(std::make_unique<TextInputElement>()));
    input->id = "tf";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    const auto a = c.RunOneCommand({{"op", "type"}, {"id", "tf"}, {"text", "AB"}});
    CHECK(a.value("ok", false) == true);
    CHECK(a["data"].at("typed") == 2);
    CHECK(input->value() == L"AB");

    // Chinese " (3 UTF-8 bytes) is rejected by the ASCII-only control: the
    // count must be 0 (not 3) and the value must not gain garbage bytes.
    const auto cn = c.RunOneCommand({{"op", "type"}, {"id", "tf"}, {"text", "中"}});
    CHECK(cn.value("ok", false) == true);
    CHECK(cn["data"].at("typed") == 0);
    CHECK(input->value() == L"AB");  // unchanged
}

// T8: toast op - show/clear/state against a ToastHost (raw text, no Str key).
static void TestDebugToast() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* host = static_cast<ToastHost*>(root.Add(std::make_unique<ToastHost>()));
    host->id = "toasts";
    root.Arrange({0, 0, 400, 300});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    const auto show = c.RunOneCommand(
        {{"op", "toast"}, {"action", "show"}, {"text", "hi"}, {"kind", "success"}});
    CHECK(show.value("ok", false) == true);
    CHECK(show["data"].at("active_count") == 1);
    CHECK(show["data"].at("toasts").is_array());
    CHECK(show["data"]["toasts"][0].value("text", std::string()) == "hi");
    CHECK(show["data"]["toasts"][0].value("kind", std::string()) == "success");

    // A 4th toast drops the oldest (kToastMax == 3).
    c.RunOneCommand({{"op", "toast"}, {"action", "show"}, {"text", "a"}});
    c.RunOneCommand({{"op", "toast"}, {"action", "show"}, {"text", "b"}});
    c.RunOneCommand({{"op", "toast"}, {"action", "show"}, {"text", "c"}});
    const auto st = c.RunOneCommand({{"op", "toast"}, {"action", "state"}});
    CHECK(st["data"].at("active_count") == 3);
    CHECK(st["data"].value("action", std::string()) == "state");

    // tick 3000ms expires every toast (TTL 3s).
    const auto tk = c.RunOneCommand({{"op", "tick"}, {"ms", 3000}});
    CHECK(tk["data"].at("toasts_expired") == 3);
    const auto st2 = c.RunOneCommand({{"op", "toast"}, {"action", "state"}});
    CHECK(st2["data"].at("active_count") == 0);

    // clear is idempotent.
    const auto cl = c.RunOneCommand({{"op", "toast"}, {"action", "clear"}});
    CHECK(cl.value("ok", false) == true);
    CHECK(cl["data"].at("active_count") == 0);
}

