// T8: dpi op - sets scale and echoes scale/dpi.
static void TestDebugDpi() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    root.Add(std::make_unique<FixedBox>(40.0f, 40.0f));
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    const auto d = c.RunOneCommand({{"op", "dpi"}, {"scale", 2.0}});
    CHECK(d.value("ok", false) == true);
    CHECK(std::fabs(d["data"].at("scale").get<double>() - 2.0) < 0.001);
    CHECK(std::fabs(d["data"].at("dpi").get<double>() - 192.0) < 0.5);
    CHECK(std::fabs(w.scale() - 2.0f) < 0.001f);
    // W11 batch12 R1 (2026-10-15): ApplyDpi must bind the renderer DPI, not
    // just the window scale. This is a coverage lock: neutralising
    // `renderer_.SetDpi(dpi_)` in VgwwWindow::ApplyDpi must turn it red.
    CHECK(std::fabs(w.renderer().dpi() - 192.0f) < 0.5f);
    const auto d125 = c.RunOneCommand({{"op", "dpi"}, {"scale", 1.25}});
    CHECK(std::fabs(d125["data"].at("dpi").get<double>() - 120.0) < 0.5);
    CHECK(std::fabs(w.renderer().dpi() - 120.0f) < 0.5f);
    const auto d15 = c.RunOneCommand({{"op", "dpi"}, {"scale", 1.5}});
    CHECK(std::fabs(w.renderer().dpi() - 144.0f) < 0.5f);
    const auto d10 = c.RunOneCommand({{"op", "dpi"}, {"scale", 1.0}});
    CHECK(std::fabs(w.renderer().dpi() - 96.0f) < 0.5f);

    // scale clamps to >= 0.5 (renderer DPI follows the clamped scale).
    const auto d2 = c.RunOneCommand({{"op", "dpi"}, {"scale", 0.1}});
    CHECK(std::fabs(d2["data"].at("scale").get<double>() - 0.5) < 0.001);
    CHECK(std::fabs(w.renderer().dpi() - 48.0f) < 0.5f);

    // missing scale is a clean error.
    const auto bad = c.RunOneCommand({{"op", "dpi"}});
    CHECK(bad.value("ok", false) == false);
}

// W11 batch12 R2b (2026-10-15): cross-scale logical invariance. The widget
// tree (logical bounds) and the recorded draw-op stream must be identical
// across simulated DPI scales - every geometry is DIP/scale-free; a scale
// leak into Measure/Arrange/Render shows up as a JSON diff. Pixel bytes are
// deliberately NOT compared across scales (AA/hinting differ by tier).
static void TestB12CrossScaleInvariance() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* btn = static_cast<Button*>(root.Add(std::make_unique<Button>(L"GO")));
    btn->id = "go";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    const nlohmann::json tree_ref = c.RunOneCommand({{"op", "tree"}})["data"];
    const nlohmann::json ops_ref = c.RunOneCommand({{"op", "draw_ops"}})["data"];

    const float scales[] = {1.25f, 1.5f, 2.0f, 1.0f, 0.5f, 1.5f};
    for (const float s : scales) {
        const auto d = c.RunOneCommand({{"op", "dpi"}, {"scale", s}});
        CHECK(d.value("ok", false) == true);
        const auto tree = c.RunOneCommand({{"op", "tree"}});
        const auto ops = c.RunOneCommand({{"op", "draw_ops"}});
        CHECK(tree.value("ok", false) == true);
        CHECK(ops.value("ok", false) == true);
        CHECK(tree["data"] == tree_ref);
        CHECK(ops["data"] == ops_ref);
    }
}

