// T8: assert extension - element_state_equals / rect_equals / toast_present /
// metric_at_least, each pass+fail.
static void TestDebugAssertExt() {
    using namespace vgww::ui;
    FixTextMetrics();
    StackPanel root(Orientation::Vertical);
    root.id = "root";
    auto* input = static_cast<TextInputElement*>(
        root.Add(std::make_unique<TextInputElement>()));
    input->id = "tf";
    input->SetValue(L"xy");
    auto* host = static_cast<ToastHost*>(root.Add(std::make_unique<ToastHost>()));
    host->id = "toasts";
    root.Arrange({0, 0, 300, 400});

    VgwwWindow w;
    w.SetRoot(&root);
    UiDebugController c;
    c.Bind(&root, &w, nullptr, nullptr);

    // element_state_equals: value key.
    const auto st_ok = c.RunOneCommand(
        {{"op", "assert"},
         {"condition", {{"element_state_equals",
                         {{"id", "tf"}, {"key", "value"}, {"value", "xy"}}}}}});
    CHECK(st_ok["data"].value("passed", false) == true);
    const auto st_bad = c.RunOneCommand(
        {{"op", "assert"},
         {"condition", {{"element_state_equals",
                         {{"id", "tf"}, {"key", "value"}, {"value", "zz"}}}}}});
    CHECK(st_bad["data"].value("passed", false) == false);

    // element_state_equals: tree-level visible.
    const auto vis_ok = c.RunOneCommand(
        {{"op", "assert"},
         {"condition", {{"element_state_equals",
                         {{"id", "tf"}, {"key", "visible"}, {"value", true}}}}}});
    CHECK(vis_ok["data"].value("passed", false) == true);

    // rect_equals: exact bounds.
    const Rect b = input->bounds();
    const auto rect_ok = c.RunOneCommand(
        {{"op", "assert"},
         {"condition", {{"rect_equals",
                         {{"id", "tf"}, {"x", b.x}, {"y", b.y},
                          {"w", b.w}, {"h", b.h}}}}}});
    CHECK(rect_ok["data"].value("passed", false) == true);

    // toast_present.
    c.RunOneCommand({{"op", "toast"}, {"action", "show"}, {"text", "yo"}});
    const auto tp_ok = c.RunOneCommand(
        {{"op", "assert"}, {"condition", {{"toast_present", "yo"}}}});
    CHECK(tp_ok["data"].value("passed", false) == true);
    const auto tp_bad = c.RunOneCommand(
        {{"op", "assert"}, {"condition", {{"toast_present", "nope"}}}});
    CHECK(tp_bad["data"].value("passed", false) == false);

    // metric_at_least.
    const auto m_ok = c.RunOneCommand(
        {{"op", "assert"},
         {"condition", {{"metric_at_least",
                         {{"key", "layout_requests"}, {"value", 0}}}}}});
    CHECK(m_ok["data"].value("passed", false) == true);
}

