// batch284: the console Copy button could not tell "nothing is selected"
// from "the clipboard write failed". `CopySelectionToClipboard()` returns
// false for BOTH, so a transient clipboard failure fell through to the
// whole-ring copy: the user selected a few lines, the write failed, and the
// ENTIRE captured log silently replaced what they thought they had copied.
static void TestB284ConsoleCopyDoesNotSubstituteAFailedSelection() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);

    int writes = 0;
    std::wstring last;
    bool fail_first = false;
    console_log::SetClipboardWriterForTest([&](const std::wstring& text) {
        ++writes;
        last = text;
        if (fail_first && writes == 1) {
            return false;  // one transient failure, then the clipboard works
        }
        return true;
    });
    console_log::ClearForTest();
    console_log::AppendForTest("sel-a");
    console_log::AppendForTest("sel-b");

    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string err;
    CHECK(controller.Start(err));
    UiSnapshot snap = MakeRulesSnapshot(1, 1);
    UiApp app;
    app.Compose(controller, snap);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    app.router().Navigate("console");
    app.Update(snap);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});

    auto* view = FindById(app.root(), "console.view");
    auto* copy = dynamic_cast<Button*>(FindById(app.root(), "console.copy"));
    CHECK(view != nullptr);
    CHECK(copy != nullptr);
    if (view == nullptr || copy == nullptr) {
        console_log::SetClipboardWriterForTest(nullptr);
        console_log::ClearForTest();
        controller.Stop();
        return;
    }

    // 1) A selection wins over the ring: exactly one write, selected lines,
    //    and a SUCCESSFUL copy must stay silent (no bogus failure toast).
    CHECK(view->SelectAllText());
    writes = 0;
    last.clear();
    const std::size_t toasts_before = app.toasts().toasts().size();
    copy->on_click();
    CHECK(app.toasts().toasts().size() == toasts_before);
    if (!app.toasts().toasts().empty()) {
        CHECK(app.toasts().toasts().back().text != Str::ConsoleCopyFailed);
    }
    CHECK(writes == 1);
    // Exact text: rows joined by \n (the view's own separator), no\r\n,
    // no ring content, no trailing newline.
    CHECK(last == L"sel-a\nsel-b");

    // 2) Grow the ring AFTER the selection was taken, so "the selection"
    //    and "the whole ring" are distinguishable (the view keeps its rows
    //    until the next Update). One transient write failure must report an
    //    error - not retry with different, much larger content.
    console_log::AppendForTest("ring-only-c");
    writes = 0;
    last.clear();
    fail_first = true;
    copy->on_click();
    // RED before the fix: the fall-through retried with the ring, so the
    // seam saw a SECOND write carrying content the user never selected.
    // The seam records the attempted text even when it refuses the write,
    // so assert on WHAT was attempted plus the call count (never on
    // "nothing was recorded" - that cannot tell a retry from no retry).
    CHECK(writes == 1);
    CHECK(last == L"sel-a\nsel-b");
    CHECK(!app.toasts().toasts().empty());
    if (!app.toasts().toasts().empty()) {
        CHECK(app.toasts().toasts().back().text == Str::ConsoleCopyFailed);
        CHECK(app.toasts().toasts().back().kind == ToastKind::Warning);
    }

    // 3) With no selection the whole ring is still the documented fallback,
    //    and it is written exactly once (no double attempt).
    CHECK(view->OnKeyDown(0x1B));  // Esc clears the selection
    writes = 0;
    last.clear();
    fail_first = false;
    copy->on_click();
    CHECK(writes == 1);
    CHECK(last.find(L"ring-only-c") != std::wstring::npos);

    // 4) A BACKWARDS drag (press low, release high) must produce the same
    //    text as the forwards one. Without the anchor/caret swap the row
    //    loop never runs, the selection text is empty, and the button
    //    silently falls back to the whole ring again.
    const Rect band = view->bounds();
    const float rx = band.x + band.w - 2.0f;
    const Point low{rx, band.y + 2.0f + 16.0f};
    const Point high{rx, band.y + 2.0f};
    view->OnMouseDown(low);
    view->OnMouseMove(high);
    view->OnMouseUp(high);
    CHECK(view->HasTextSelection());
    writes = 0;
    last.clear();
    copy->on_click();
    CHECK(writes == 1);
    // Row 0 is clipped at its caret (end of "sel-a"), row 1 is copied in
    // full up to its anchor (end of "sel-b").
    CHECK(last == L"\nsel-b");

    console_log::SetClipboardWriterForTest(nullptr);
    console_log::ClearForTest();
    controller.Stop();
}

// batch285: the text input's Cut destroyed the selection even when the
// clipboard write failed (its helper `SetClipboardText` swallowed every
// Win32 error and `CutSelectionToClipboard` returned true unconditionally),
// and Copy reported success for a write that never happened. The console
// log already had a failure-aware writer; the input had a silent duplicate.
static void TestB285TextInputCutKeepsTextWhenClipboardRefuses() {
    using namespace vgww::ui;
    FixTextMetrics();

    int writes = 0;
    std::wstring copied;
    bool refuse = false;
    console_log::SetClipboardWriterForTest([&](const std::wstring& text) {
        ++writes;
        copied = text;
        return !refuse;
    });

    TextInputElement input;
    input.SetValue(L"hello world");
    input.SetSelectionForTest(0, 5);  // "hello"
    CHECK(input.SelectedText() == L"hello");

    // (1) Cut with a refusing clipboard must NOT destroy the text.
    refuse = true;
    writes = 0;
    copied.clear();
    CHECK(!input.CutSelectionToClipboard());     // RED: old code returned true
    CHECK(input.value() == L"hello world");      // RED: old code deleted it
    CHECK(writes == 1);                          // RED: old code never asked
    CHECK(copied == L"hello");
    CHECK(input.SelectedText() == L"hello");     // selection survives too

    // (2) Copy must report the failure instead of pretending.
    writes = 0;
    copied.clear();
    CHECK(!input.CopySelectionToClipboard());    // RED: old code returned true
    CHECK(writes == 1);
    CHECK(copied == L"hello");                   // the SELECTION, not the field
    CHECK(input.value() == L"hello world");

    // (3) Success path is unchanged: one write, then the deletion.
    refuse = false;
    writes = 0;
    copied.clear();
    CHECK(input.CutSelectionToClipboard());
    CHECK(writes == 1);
    CHECK(copied == L"hello");
    CHECK(input.value() == L" world");
    CHECK(input.caret_index() == 0);

    // (4) An empty selection is not a clipboard operation at all.
    writes = 0;
    CHECK(!input.CutSelectionToClipboard());
    CHECK(!input.CopySelectionToClipboard());
    CHECK(writes == 0);

    console_log::SetClipboardWriterForTest(nullptr);
}
// batch287: the window used to swallow clipboard failures. The edit menu
// (ShowEditContextMenu) and the Ctrl+C/Ctrl+X paths dropped the bool that
// batches 284/285 made truthful, so a clipboard held by another process made
// Copy/Cut look like a no-op with no feedback at all. The window now reports
// through `on_clipboard_failed`; the shell turns it into the same warning
// toast the pages use. Shift+Delete must also stop falling through to the
// plain Delete handler, which erased the selection (the batch285 data loss).
static void TestB287ClipboardFailureIsReported() {
    using namespace vgww::ui;
    FixTextMetrics();

    int writes = 0;
    bool refuse = true;
    console_log::SetClipboardWriterForTest([&](const std::wstring&) {
        ++writes;
        return !refuse;
    });

    StackPanel root(Orientation::Vertical);
    auto* input = static_cast<TextInputElement*>(
        root.Add(std::make_unique<TextInputElement>()));
    input->SetValue(L"abcdef");
    auto menu_up = std::make_unique<ContextMenu>();
    auto* menu = menu_up.get();
    root.Add(std::move(menu_up));
    root.Arrange(Rect{0.0f, 0.0f, 600.0f, 200.0f});

    VgwwWindow w;
    w.SetRoot(&root);
    w.SetEditContextMenu(menu);
    w.SetFocusForTest(input);
    int failures = 0;
    w.on_clipboard_failed = [&](bool) { ++failures; };

    // (1) Ctrl+C while the clipboard refuses: one report, text untouched.
    input->SetSelectionForTest(0, 3);
    w.SetModifiersForTest(0x2u);
    writes = 0;
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x43));  // VK_C, consumed
    CHECK(failures == 1);  // RED: the old window said nothing
    CHECK(writes == 1);
    CHECK(input->value() == L"abcdef");
    CHECK(input->SelectedText() == L"abc");

    // (2) Ctrl+X while refusing: one report and the text must survive.
    writes = 0;
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x58));  // VK_X, consumed
    CHECK(failures == 2);
    CHECK(writes == 1);
    CHECK(input->value() == L"abcdef");
    CHECK(input->SelectedText() == L"abc");
    w.ResetModifiersForTest();

    // (3) Ctrl+C with no selection is not a clipboard operation: no toast.
    input->SetSelectionForTest(3, 3);
    w.SetModifiersForTest(0x2u);
    writes = 0;
    CHECK(!w.RouteKeyForTest(WM_KEYDOWN, 0x43));
    CHECK(failures == 2);  // RED: a blanket "false = failed" cries wolf
    CHECK(writes == 0);
    w.ResetModifiersForTest();

    // (4) A successful copy stays silent.
    refuse = false;
    input->SetSelectionForTest(0, 3);
    w.SetModifiersForTest(0x2u);
    writes = 0;
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x43));
    CHECK(failures == 2);
    CHECK(writes == 1);
    w.ResetModifiersForTest();

    // (4b) The classic shortcuts are clipboard operations too. A refusal is
    // reported and the key is consumed; crucially Shift+Delete must NOT fall
    // through to the plain Delete handler, which erases the selection - the
    // same data loss batch285 fixed for Ctrl+X, still reachable here.
    refuse = true;
    input->SetSelectionForTest(0, 3);
    w.SetModifiersForTest(0x2u);  // Ctrl+Insert = copy
    writes = 0;
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x2D));
    CHECK(failures == 3);
    CHECK(writes == 1);
    w.ResetModifiersForTest();
    w.SetModifiersForTest(0x1u);  // Shift+Delete = cut
    writes = 0;
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x2E));
    CHECK(failures == 4);
    CHECK(writes == 1);
    CHECK(input->value() == L"abcdef");      // RED: fell through to Delete
    CHECK(input->SelectedText() == L"abc");  // RED: selection was erased
    w.ResetModifiersForTest();

    // (5) The right-click edit menu reports the same failure, both items.
    refuse = true;
    input->SetSelectionForTest(0, 3);
    const Rect ib = input->bounds();
    const Point at{ib.x + 6.0f + 8.0f, ib.y + 14.0f};
    w.RouteMouseForTest(WM_RBUTTONUP, at);
    CHECK(menu->open());
    int copy_index = -1;
    int cut_index = -1;
    for (std::size_t i = 0; i < menu->items().size(); ++i) {
        if (menu->items()[i].label == I18n::Instance().T(Str::ConsoleCopy)) {
            copy_index = static_cast<int>(i);
        }
        if (menu->items()[i].label == I18n::Instance().T(Str::EditCut)) {
            cut_index = static_cast<int>(i);
        }
    }
    CHECK(copy_index >= 0);
    CHECK(cut_index >= 0);
    if (copy_index >= 0) {
        menu->Activate(copy_index);
    }
    CHECK(failures == 5);  // RED: the menu copy dropped the result
    if (cut_index >= 0) {
        w.RouteMouseForTest(WM_RBUTTONUP, at);  // re-open after Activate
        CHECK(menu->open());
        menu->Activate(cut_index);
    }
    CHECK(failures == 6);  // RED: the menu cut dropped the result
    CHECK(input->value() == L"abcdef");

    w.SetEditContextMenu(nullptr);
    w.SetRoot(nullptr);
    console_log::SetClipboardWriterForTest(nullptr);

    // (6) The shell turns the hook into the same warning the pages show.
    {
        ShellFakeSource source;
        ShellFakeExecutor executor;
        UiController controller(source, executor);
        UiSnapshot first;
        first.seq = 1;
        UiApp app;
        app.Compose(controller, first);
        CHECK(app.window().on_clipboard_failed != nullptr);
        app.toasts().Clear();
        if (app.window().on_clipboard_failed) {
            app.window().on_clipboard_failed(false);
        }
        CHECK(app.toasts().toasts().size() == 1);
        const ToastEntry* shown = app.toasts().toasts().empty()
                                      ? nullptr
                                      : &app.toasts().toasts().back();
        CHECK(shown != nullptr && shown->text == Str::ConsoleCopyFailed);
        CHECK(shown != nullptr && shown->kind == ToastKind::Warning);
    }
    FixTextMetrics();
}
// batch288: the clipboard READ had no failure channel. `GetClipboardText`
// returned an empty string for BOTH "nothing on the clipboard" and "could
// not open the clipboard", so Ctrl+V / Shift+Insert / the edit menu silently
// did nothing whenever another process held the clipboard - and the menu
// even HID the paste item.
static void TestB288PasteFailureIsReported() {
    using namespace vgww::ui;
    FixTextMetrics();

    int reads = 0;
    bool read_ok = false;
    std::wstring read_text;
    console_log::SetClipboardReaderForTest([&](std::wstring& out) {
        ++reads;
        out = read_text;
        return read_ok;
    });

    StackPanel root(Orientation::Vertical);
    auto* input = static_cast<TextInputElement*>(
        root.Add(std::make_unique<TextInputElement>()));
    input->SetValue(L"abcdef");
    auto menu_up = std::make_unique<ContextMenu>();
    auto* menu = menu_up.get();
    root.Add(std::move(menu_up));
    root.Arrange(Rect{0.0f, 0.0f, 600.0f, 200.0f});

    VgwwWindow w;
    w.SetRoot(&root);
    w.SetEditContextMenu(menu);
    w.SetFocusForTest(input);
    int failures = 0;
    int paste_reports = 0;
    w.on_clipboard_failed = [&](bool paste) {
        ++failures;
        paste_reports += paste ? 1 : 0;
    };

    // (1) Ctrl+V while the clipboard cannot be read: reported as a PASTE
    // failure, the key is consumed, and nothing is inserted.
    input->SetSelectionForTest(6, 6);
    read_ok = false;
    read_text.clear();
    reads = 0;
    w.SetModifiersForTest(0x2u);
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x56));  // VK_V, consumed
    CHECK(failures == 1);      // RED: the old window said nothing
    CHECK(paste_reports == 1); // RED: and nothing said "paste"
    CHECK(reads == 1);
    CHECK(input->value() == L"abcdef");
    w.ResetModifiersForTest();

    // (2) An EMPTY clipboard is not a failure: no report, not consumed.
    read_ok = true;
    read_text.clear();
    reads = 0;
    w.SetModifiersForTest(0x2u);
    CHECK(!w.RouteKeyForTest(WM_KEYDOWN, 0x56));
    CHECK(failures == 1);  // unchanged: empty != failed
    CHECK(reads == 1);
    w.ResetModifiersForTest();

    // (3) A successful paste inserts once and stays silent.
    read_text = L"XY";
    reads = 0;
    w.SetModifiersForTest(0x2u);
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x56));
    CHECK(failures == 1);
    CHECK(reads == 1);
    CHECK(input->value() == L"abcdefXY");
    w.ResetModifiersForTest();

    // (4) Shift+Insert is the same operation: failure reported as paste.
    read_ok = false;
    input->SetSelectionForTest(8, 8);
    w.SetModifiersForTest(0x1u);
    CHECK(w.RouteKeyForTest(WM_KEYDOWN, 0x2D));
    CHECK(failures == 2);
    CHECK(paste_reports == 2);
    CHECK(input->value() == L"abcdefXY");
    w.ResetModifiersForTest();

    // (5) The edit menu must still OFFER paste when the clipboard is
    // unreadable (hiding it leaves the user no way to learn why).
    read_ok = false;
    const Rect ib = input->bounds();
    const Point at{ib.x + 6.0f + 8.0f, ib.y + 14.0f};
    w.RouteMouseForTest(WM_RBUTTONUP, at);
    CHECK(menu->open());
    int paste_index = -1;
    for (std::size_t i = 0; i < menu->items().size(); ++i) {
        if (menu->items()[i].label == I18n::Instance().T(Str::EditPaste)) {
            paste_index = static_cast<int>(i);
        }
    }
    CHECK(paste_index >= 0);  // RED: old code hid it on a failed read
    if (paste_index >= 0) {
        menu->Activate(paste_index);
    }
    CHECK(failures == 3);
    CHECK(paste_reports == 3);
    CHECK(input->value() == L"abcdefXY");

    // (6) ... but an EMPTY clipboard still hides it: nothing to paste.
    read_ok = true;
    read_text.clear();
    w.RouteMouseForTest(WM_RBUTTONUP, at);
    CHECK(menu->open());
    bool has_paste = false;
    for (std::size_t i = 0; i < menu->items().size(); ++i) {
        if (menu->items()[i].label == I18n::Instance().T(Str::EditPaste)) {
            has_paste = true;
        }
    }
    CHECK(!has_paste);
    menu->Close();

    w.SetEditContextMenu(nullptr);
    w.SetRoot(nullptr);
    console_log::SetClipboardReaderForTest(nullptr);

    // (7) The shell shows the matching message for each kind.
    {
        ShellFakeSource source;
        ShellFakeExecutor executor;
        UiController controller(source, executor);
        UiSnapshot first;
        first.seq = 1;
        UiApp app;
        app.Compose(controller, first);
        CHECK(app.window().on_clipboard_failed != nullptr);
        app.toasts().Clear();
        if (app.window().on_clipboard_failed) {
            app.window().on_clipboard_failed(true);
        }
        CHECK(app.toasts().toasts().size() == 1);
        const ToastEntry* pt = app.toasts().toasts().empty()
                                  ? nullptr
                                  : &app.toasts().toasts().back();
        CHECK(pt != nullptr && pt->text == Str::ClipboardPasteFailed);
        CHECK(pt != nullptr && pt->kind == ToastKind::Warning);
        app.toasts().Clear();
        if (app.window().on_clipboard_failed) {
            app.window().on_clipboard_failed(false);
        }
        const ToastEntry* ct = app.toasts().toasts().empty()
                                  ? nullptr
                                  : &app.toasts().toasts().back();
        CHECK(ct != nullptr && ct->text == Str::ConsoleCopyFailed);
    }
    FixTextMetrics();
}

// ============================================================================
// Batch20 (option : the Settings page scrolls its OWN content. The page
// already built a ScrollView, but without fill_remaining the surrounding
// StackPanel measured it at its full content height, so it never became a
// viewport and every group below the fold - including the 17-step UI scale
// select - was unreachable. Anchor: in a 980x640 window the viewport must be
// shorter than the content, and scrolling to the end must bring the UI group
// into view.
// batch292: the port-map page learned in batch264 that a row id which no
// longer matches any rule must NOT open a delete confirmation: it used to
// fall back to the raw id, show "Delete 0?" and then queue a command
// against id 0. The firewall delete path still does exactly that - it falls
// back to Widen(row_id) and confirms a bare number the user cannot
// recognise, then removes whatever now owns that id.
static void TestB292FirewallDeleteRejectsStaleId() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string error;
    CHECK(controller.Start(error));

    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    snapshot.bans.clear();
    snapshot.bans.push_back(vgww::web::BanEntry{"mac", "02:00:00:00:00:05", 5});

    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 900.0f});
    app.router().Navigate("firewall");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 900.0f});

    auto* table =
        dynamic_cast<TableElement*>(FindById(app.root(), "firewall.table"));
    auto* dialog = dynamic_cast<DialogHost*>(
        FindById(app.root(), "firewall.dialog"));
    CHECK(table != nullptr);
    CHECK(dialog != nullptr);
    if (table == nullptr || dialog == nullptr) {
        controller.Stop();
        return;
    }
    CHECK(table->rows().size() == 1);

    // (1) An id that matches NOTHING must not open a confirmation and must
    // not queue a command - not even after an OK is pressed.
    for (const char* stale : {"99", "0", "12345"}) {
        dialog->Close();  // drop any dialog the previous iteration opened
        executor.commands.clear();
        table->on_row_action(stale, 0);
        CHECK(!dialog->open());        // RED: opens with a bare id today
        CHECK(executor.commands.empty());
    }

    // (2) A malformed id is rejected by the parser as well.
    for (const char* bad : {"", "abc", "9x", "-9", " 9"}) {
        dialog->Close();
        executor.commands.clear();
        table->on_row_action(bad, 0);
        CHECK(!dialog->open());
        CHECK(executor.commands.empty());
    }

    // (3) The LIVE id still confirms, names the ban, and queues that id.
    executor.commands.clear();
    table->on_row_action("5", 0);
    CHECK(dialog->open());
    CHECK(dialog->mode() == DialogHost::Mode::Confirm);
    CHECK(DialogHasSubtext(*dialog, L"mac 02:00:00:00:00:05"));
    CHECK(dialog->OnKeyDown(0x0D));
    CHECK(WaitForCommands(executor, 1, controller));
    CHECK(executor.commands.size() == 1);
    if (executor.commands.size() == 1) {
        const auto* cmd = std::get_if<RemoveBanCmd>(&executor.commands[0]);
        CHECK(cmd != nullptr && cmd->id == 5);
    }

    controller.Stop();
    FixTextMetrics();
}
// ============================================================================
// ============================================================================
// Batch20: single-instance gate predicate. A TEST launch (--ui-debug-port /
// --ui-page / --headless, either "--flag value" or "--flag=value") bypasses the
// gate so the automation pipelines can run parallel short-lived instances; any
// other launch is gated and activates the running window instead.
// ============================================================================
static void TestB20SingleInstancePredicate() {
    using namespace vgww::ui;
    CHECK(!IsTestLaunch({}));  // a plain launch is gated
    CHECK(!IsTestLaunch({"--config=x.json"}));
    CHECK(!IsTestLaunch({"--config", "x.json"}));
    CHECK(IsTestLaunch({"--ui-debug-port=19777"}));
    CHECK(IsTestLaunch({"--ui-debug-port", "19777"}));
    CHECK(IsTestLaunch({"--ui-page=about"}));
    CHECK(IsTestLaunch({"--headless"}));
    CHECK(IsTestLaunch({"--config=x.json", "--headless"}));
    CHECK(IsTestLaunchFlag("--ui-page=leases"));
    CHECK(!IsTestLaunchFlag("--ui-pages=x"));
    // batch120: same constant-condition hoist as above.
    constexpr bool kActivateIsAppRange = kActivateMessage >= WM_APP;
    CHECK(kActivateIsAppRange);
}
static void TestB20SettingsScrollReach() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string err;
    CHECK(controller.Start(err));
    UiSnapshot snap = MakeRulesSnapshot(1, 1);
    UiApp app;
    app.Compose(controller, snap);
    app.root().Arrange({0.0f, 0.0f, 980.0f, 640.0f});
    app.router().Navigate("settings");
    app.Update(snap);
    app.root().Arrange({0.0f, 0.0f, 980.0f, 640.0f});

    auto* scroll = dynamic_cast<ScrollView*>(
        FindById(app.root(), "settings.scroll"));
    auto* ui_group = FindById(app.root(), "settings.group.ui");
    auto* scale = dynamic_cast<SelectElement*>(
        FindById(app.root(), "settings.ui_scale"));
    CHECK(scroll != nullptr);
    CHECK(ui_group != nullptr);
    CHECK(scale != nullptr);
    // batch25a: the professional groups live in the collapsed "Advanced
    // settings" tier now; expand it (one click) before probing scroll reach.
    auto* advanced_toggle = dynamic_cast<Button*>(
        FindById(app.root(), "settings.advanced.toggle"));
    CHECK(advanced_toggle != nullptr);
    if (advanced_toggle != nullptr) {
        ClickElement(*advanced_toggle);
        app.root().Arrange({0.0f, 0.0f, 980.0f, 640.0f});
    }
    if (scroll != nullptr && ui_group != nullptr) {
        // The ScrollView is a real viewport, not the full content height.
        CHECK(scroll->content_height() > scroll->view_height());
        CHECK(scroll->view_height() > 0.0f);
        // The UI group starts below the fold...
        // Even at a very small window the page stays a scrollable viewport
        // (nothing is silently clipped away).
        app.root().Arrange({0.0f, 0.0f, 980.0f, 300.0f});
        CHECK(scroll->content_height() > scroll->view_height());
        CHECK(scroll->view_height() <= 300.0f);
        app.root().Arrange({0.0f, 0.0f, 980.0f, 640.0f});
        CHECK(ui_group->bounds().y >=
              scroll->bounds().y + scroll->view_height() - 0.5f);
        // ...and is reachable by scrolling to the end.
        scroll->OnWheel(-120);  // wheel-down scrolls toward the end
        CHECK(scroll->offset() > 0.0f);
        scroll->SetOffset(scroll->content_height());
        app.root().Arrange({0.0f, 0.0f, 980.0f, 640.0f});
        const float view_bottom = scroll->bounds().y + scroll->view_height();
        CHECK(ui_group->bounds().y < view_bottom);
        if (scale != nullptr) {
            CHECK(scale->bounds().y + scale->bounds().h <= view_bottom + 1.0f);
        }
    }
    I18n::Instance().SetLang(Lang::ZhCN);
}

// ============================================================================
// Batch20 P5: a long localized banner reason must stay INSIDE the banner - the
// Japanese text used to run under the repair button and past the amber border.
// Anchor: the reason text op is clamped to the band before the action, and the
// children are clipped to the banner frame.
// ============================================================================
static void TestB20BannerReasonClamp() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLangCode("ja");

    DriverBanner banner;
    const std::wstring kLong =
        L"データプレーンが停止していません ndisrd ドライバーがインストールされ"
        L"ていません。「管理者として修復」をクリックして UAC を承認するか、"
        L"管理者権限で vgww.exe --install-driver を実行してから VGWW を再起動して"
        L"ください";
    banner.SetFailure(true, L"データプレーンが停止していません", kLong);
    banner.Arrange({236.0f, 88.0f, 728.0f, 44.0f});
    RenderCtx ctx;
    ctx.BeginRecord();
    banner.Render(ctx);
    ctx.EndRecord();

    const float right = 236.0f + 728.0f;
    float action_left = -1.0f;
    if (banner.action_button() != nullptr) {
        action_left = banner.action_button()->bounds().x;
    }
    bool reason_seen = false, clipped = false;
    for (const auto& op : ctx.ops()) {
        if (op.kind == DrawOp::Kind::ClipPush) {
            clipped = true;
        }
        if (op.kind == DrawOp::Kind::DrawText && op.text == kLong) {
            reason_seen = true;
            CHECK(op.rect.x >= 236.0f - 0.5f);
            CHECK(op.rect.x + op.rect.w <= right + 0.5f);  // inside the frame
            // The discriminating anchor: the reason band must STOP before the
            // repair button (the unbounded version ran underneath it).
            CHECK(action_left > 0.0f);
            CHECK(op.rect.x + op.rect.w <= action_left - 2.0f);
        }
    }
    CHECK(reason_seen);
    CHECK(clipped);
    // The repair button keeps the trailing edge (not overrun by the reason).
    auto* action = banner.action_button();
    CHECK(action != nullptr);
    if (action != nullptr) {
        CHECK(action->bounds().x + action->bounds().w <= right - 16.0f + 0.5f);
    }
    I18n::Instance().SetLangCode("zh-CN");
}

// ============================================================================
// batch120: the disk log is appended across sessions, so the rollover budget
// belongs to the FILE, not to the run. The open path used ::ftell() on a
// freshly opened append-mode stream, which reports 0 - a log left behind by a
// previous run therefore looked empty, g_log_bytes restarted from zero, and the
// file could grow to roughly twice the configured limit before it rolled.
// Given a log that already exceeds the limit, WHEN the next session opens it
// and writes one line, THEN it must roll immediately instead of appending on
// top of the old bytes.
static void TestB120LogRolloverCountsPreexistingBytes() {
    using namespace vgww::ui;
    const std::wstring dir = TempDir(L"b120-log-test");
    console_log::CloseLogFileForTest();
    console_log::SetLogDirForTest(dir);
    console_log::SetLogRolloverBytesForTest(64);
    console_log::ClearForTest();

    std::error_code ec;
    std::filesystem::remove_all(dir, ec);
    std::filesystem::create_directories(dir, ec);
    const std::filesystem::path log = std::filesystem::path(dir) / L"vgww.log";
    const std::filesystem::path rolled =
        std::filesystem::path(dir) / L"vgww.log.1";

    // A previous session left 400 bytes behind.
    {
        std::ofstream out(log, std::ios::binary);
        CHECK(out.good());
        for (int i = 0; i < 10; ++i) {
            out << "preexisting-line-padding-0123456789abcdef\r\n";
        }
    }
    const auto before = std::filesystem::file_size(log, ec);
    CHECK(!ec);
    CHECK(before > 64);
    CHECK(!std::filesystem::exists(rolled));

    CHECK(console_log::OpenLogFileForTest());
    console_log::AppendForTest("first-line-of-the-new-run");

    // The stale bytes must have been rotated away BEFORE the new line landed,
    // so the live file starts over and the old content is preserved as .1.
    CHECK(std::filesystem::exists(rolled));
    const auto after = std::filesystem::file_size(log, ec);
    CHECK(!ec);
    CHECK(after < before);
    {
        std::ifstream in(log, std::ios::binary);
        std::stringstream buf;
        buf << in.rdbuf();
        const std::string text = buf.str();
        CHECK(text.find("first-line-of-the-new-run") != std::string::npos);
    }
    {
        std::ifstream in(rolled, std::ios::binary);
        std::stringstream buf;
        buf << in.rdbuf();
        const std::string text = buf.str();
        CHECK(text.find("preexisting-line-padding") != std::string::npos);
    }

    console_log::CloseLogFileForTest();
    console_log::SetLogDirForTest(L"");
    console_log::SetLogRolloverBytesForTest(5u * 1024u * 1024u);
    console_log::ClearForTest();
    std::filesystem::remove_all(dir, ec);
}


// Batch20 P6: the console's captured output is teed to a local log file
// (append across sessions, size-rolled to vgww.log.1). Anchor: the file holds
// exactly the injected lines, and exceeding the (test) rollover renames it.
// ============================================================================
static void TestB20ConsoleDiskLog() {
    using namespace vgww::ui;
    FixTextMetrics();
    const std::wstring dir =
        TempDir(L"b20-console-log-test");
    console_log::CloseLogFileForTest();
    console_log::SetLogDirForTest(dir);
    console_log::SetLogRolloverBytesForTest(64);  // force a roll quickly
    console_log::ClearForTest();
    // batch120: this test asserts on the FIRST bytes of the live log, so it
    // must not inherit a log (or a .1) from an earlier run. The rollover
    // budget is now counted from the real file size, so stale bytes would
    // rotate alpha-line-1 away before the read below.
    {
        std::error_code clean_ec;
        std::filesystem::remove_all(dir, clean_ec);
    }
    CHECK(console_log::OpenLogFileForTest());
    const std::wstring path =
        TempDir(L"b20-console-log-test") + L"\\vgww.log";
    CHECK(console_log::LogFilePath() == path);

    console_log::AppendForTest("alpha-line-1");
    console_log::AppendForTest("beta-line-2");
    {
        std::ifstream in(TempDirNarrow("b20-console-log-test") + "\\vgww.log",
                         std::ios::binary);
        CHECK(in.good());
        std::stringstream buffer;
        buffer << in.rdbuf();
        const std::string text = buffer.str();
        CHECK(text.find("alpha-line-1") != std::string::npos);
        CHECK(text.find("beta-line-2") != std::string::npos);
    }
    // Exceed the rollover: the file is renamed to vgww.log.1 and restarted.
    for (int i = 0; i < 12; ++i) {
        console_log::AppendForTest(
            "rollover-padding-line-that-is-long-enough-to-pass-64-bytes");
    }
    CHECK(std::filesystem::exists(
        TempDirNarrow("b20-console-log-test") + "\\vgww.log.1"));
    console_log::CloseLogFileForTest();
    console_log::SetLogDirForTest(L"");
    console_log::SetLogRolloverBytesForTest(5u * 1024u * 1024u);
    console_log::ClearForTest();
    I18n::Instance().SetLang(Lang::ZhCN);
}

