    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});

    auto* nav_leases = dynamic_cast<Button*>(
        FindById(app.root(), "shell.nav.leases"));
    CHECK(nav_leases != nullptr);
    // Any expanded popup on the page must be collapsed by the switch. Drive it
