    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string error;
    CHECK(controller.Start(error));

    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    snapshot.config.adapter = "NIC 1";
    snapshot.config.mode = "bypass";
    // A save must pass SettingsDraft::ToConfig, which validates the address
    // fields; give the fixture a complete, valid config.
    snapshot.config.gateway_ip = "192.168.1.1";
    snapshot.config.gateway_mask = "255.255.255.0";
    snapshot.config.gateway_mac = "02:00:00:00:00:01";
