// P1-14: a modal opens with the keyboard on its SAFE button (Cancel when it
// has one), and Enter still triggers the default (primary) action.
static void TestB27DialogSafeDefaultFocus() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    auto root = std::make_unique<StackPanel>(Orientation::Vertical, 8.0f);
    auto* page_button = static_cast<Button*>(
        root->Add(std::make_unique<Button>(L"Page")));
    page_button->id = "b27.page";
    auto* dialog = static_cast<DialogHost*>(
        root->Add(std::make_unique<DialogHost>()));
    dialog->id = "b27.dialog";
    int oks = 0;
    dialog->ShowConfirmActionsText(L"t", L"b", L"Delete", L"Keep",
                                   [&oks] { ++oks; });
    root->Arrange({0.0f, 0.0f, 500.0f, 400.0f});

    VgwwWindow window;
    window.SetRoot(root.get());
    window.ResizeForTest(500.0f, 400.0f);
    root->Arrange({0.0f, 0.0f, 500.0f, 400.0f});
    window.SetFocusForTest(page_button);  // the page holds focus behind the mask

    // The first key press moves focus to the dialog's safe button.
    CHECK(window.RouteKeyForTest(WM_KEYDOWN, 0x09));  // VK_TAB
    Element* focused = window.FocusedForTest();
    CHECK(focused != nullptr);
    CHECK(ElementInTree(dialog, focused));  // never the masked page
    if (focused != nullptr) {
        CHECK(focused->id == "dialog.cancel");  // red: the page button kept focus
    }
    // Esc cancels without firing the destructive action.
    CHECK(window.RouteKeyForTest(WM_KEYDOWN, 0x1B));
    CHECK(!dialog->open());
    CHECK(oks == 0);
    SweepRetiredDialogChrome();
}

// P1-15: links ease their hover exactly like buttons (one shared duration).
static void TestB27LinkHoverTransition() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    LinkElement link(L"docs", L"https://example.invalid");
    link.Arrange({0.0f, 0.0f, 120.0f, 24.0f});
    CHECK(link.hover_progress() == 0.0f);
    link.OnMouseMove({10.0f, 10.0f});
    CHECK(link.hovered());
    CHECK(link.hover_progress() == 0.0f);   // starts at rest
    CHECK(link.HasActiveAnimation());       // red: no transition existed
    link.AdvanceAnimation(0.06f);           // half of kHoverSeconds (0.12)
    CHECK(std::fabs(link.hover_progress() - 0.5f) < 0.01f);
    link.AdvanceAnimation(0.06f);
    CHECK(link.hover_progress() == 1.0f);
    CHECK(!link.HasActiveAnimation());
    link.OnMouseMove({500.0f, 500.0f});
    CHECK(!link.hovered());
    CHECK(link.HasActiveAnimation());
    link.AdvanceAnimation(0.12f);
    CHECK(link.hover_progress() == 0.0f);
}

// D2: an empty table centres its placeholder in the region BELOW the header
// band, so the whitespace above and below the message matches (<= 8 px).
static void TestB27EmptyStateCentring() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    auto root = std::make_unique<StackPanel>(Orientation::Vertical, 0.0f);
    auto fill = std::make_unique<FillPanel>();
    fill->fill_remaining = true;
    auto* table = fill->SetTable(std::make_unique<TableElement>());
    table->SetColumns(std::vector<TableColumn>{
        TableColumn{"a", Str::ColMac, 100.0f, Align::Start}});
    auto* empty = fill->SetEmpty(
        std::make_unique<EmptyState>(Str::LeasesEmptyHint));
    root->Add(std::move(fill));
    root->Arrange({0.0f, 0.0f, 600.0f, 400.0f});

    CHECK(table->bounds().h > 0.0f);
    const float header_bottom = table->bounds().y + TableElement::header_height();
    const float region_bottom = table->bounds().y + table->bounds().h;
    const float above = empty->bounds().y - header_bottom;
    const float below =
        region_bottom - (empty->bounds().y + empty->bounds().h);
    CHECK(above >= 0.0f);
    CHECK(std::fabs(above - below) <= 8.0f);  // red: centred in the whole box
}

// D1: the port-map / firewall column weights give the value columns the room
// they need (a 15-char IPv4 must not be squeezed by a 3-char protocol cell).
static void TestB27TableColumnWeights() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string error;
    CHECK(controller.Start(error));
    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    snapshot.portmaps.push_back(
        vgww::web::PortMappingRule{"tcp", 8080, "192.168.100.200", 8080});
    snapshot.bans.push_back(vgww::web::BanEntry{"mac", "AA:BB:CC:DD:EE:FF"});
    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});

    app.router().Navigate("portmap");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    auto* pm = dynamic_cast<TableElement*>(FindById(app.root(), "portmap.table"));
    CHECK(pm != nullptr);
    if (pm != nullptr && pm->resolved_widths().size() == 4) {
        const auto& w = pm->resolved_widths();
        // Protocol (index 0) is short text; it must not dominate the table.
        // batch29: auto widths keep every column at its measured content width
        // (the fixed 100 px stub makes the text columns equal) and stretch
        // them proportionally - the short "tcp" column must still be the
        // narrowest or equal, never the widest.
        CHECK(w[0] <= w[2] + 0.01f);              // proto <= LAN IP
        CHECK(w[2] >= 108.0f);                    // room for a full IPv4 + inset
        CHECK(w[0] >= 108.0f);                    // still readable
    }

    app.router().Navigate("firewall");
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    auto* fw = dynamic_cast<TableElement*>(FindById(app.root(), "firewall.table"));
    CHECK(fw != nullptr);
    if (fw != nullptr && fw->resolved_widths().size() == 2) {
        const auto& w = fw->resolved_widths();
        // kind (3 chars) vs value (MAC/IP): with the fixed 100 px measure stub
        // both measure equal; batch29 keeps each at its content width and the
        // table fills exactly.
        CHECK(w[0] <= w[1] + 0.01f);
        CHECK(w[1] >= 108.0f);
    }
    controller.Stop();
}

// batch27 x batch29: a content-driven (`auto_width`) table must still honour
// `max_width`. The content path used to return before the cap pass, so a
// "tcp" column could grow to the widest measured column and the port columns
// stole the width the LAN IP column needs.
static void TestB27AutoWidthHonoursMaxWidth() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);

    TableElement table;
    table.SetColumns(std::vector<TableColumn>{
        TableColumn{"proto", Str::ColProto, 60.0f, Align::Start, 120.0f, true},
        TableColumn{"wan_port", Str::ColWanPort, 100.0f, Align::End, 160.0f,
                    true},
        TableColumn{"lan_ip", Str::ColLanIp, 200.0f, Align::Start, 0.0f, true},
        TableColumn{"lan_port", Str::ColLanPort, 100.0f, Align::End, 160.0f,
                    true}});
    table.SetRows(std::vector<TableRow>{
        TableRow{"r1", {L"tcp", L"65535", L"255.255.255.255", L"65535"}}});
    table.Arrange({0.0f, 0.0f, 1028.0f, 400.0f});

    const auto& w = table.resolved_widths();
    CHECK(w.size() == 4);
    if (w.size() == 4) {
        // Every capped column stays at or below its cap...
        CHECK(w[0] <= 120.0f + 0.5f);
        CHECK(w[1] <= 160.0f + 0.5f);
        CHECK(w[3] <= 160.0f + 0.5f);
        // ...and the table still fills its width exactly.
        const float sum = w[0] + w[1] + w[2] + w[3];
        CHECK(std::fabs(sum - 1028.0f) < 1.0f);
        // The protocol column must never be the widest column.
        CHECK(w[0] < w[2]);
    }
}

