// D6: the dashboard's status strip has exactly one primary action.
static void TestB27DashboardSinglePrimary() {
    using namespace vgww::ui;
    FixTextMetrics();
    I18n::Instance().SetLang(Lang::ZhCN);
    ShellFakeSource source;
    RecordingExecutor executor;
    UiController controller(source, executor);
    std::string error;
    CHECK(controller.Start(error));
    UiSnapshot snapshot = MakeRulesSnapshot(1, 1);
    snapshot.dataplane_running = true;
    UiApp app;
    app.Compose(controller, snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});
    app.Update(snapshot);
    app.root().Arrange({0.0f, 0.0f, 1280.0f, 800.0f});

    std::size_t primaries = 0;
    std::vector<Element*> stack{&app.root()};
    while (!stack.empty()) {
        Element* node = stack.back();
        stack.pop_back();
        if (!node->visible) {
            continue;
        }
        if (auto* button = dynamic_cast<Button*>(node)) {
            if (button->style() == ButtonStyle::Primary) {
                ++primaries;
            }
        }
        for (const auto& child : node->children()) {
            stack.push_back(child.get());
        }
    }
    // batch27 D6: while RUNNING, "stop service" is not promoted - the strip
    // carries no primary at all (help/stop are both Secondary), so the page
    // never shows two competing primaries. (The stopped+configured state is
    // covered by TestB27DashboardSetupButton: exactly one primary there.)
    CHECK(primaries == 0);
    auto* action = dynamic_cast<Button*>(FindById(app.root(), "dash.action"));
    auto* help = dynamic_cast<Button*>(FindById(app.root(), "dash.help"));
    CHECK(action != nullptr && action->style() == ButtonStyle::Secondary);
    CHECK(help != nullptr && help->style() == ButtonStyle::Secondary);
    controller.Stop();
}

